const std = @import("std");
const tensorcore = @cImport(@cInclude("tensorcore.h"));
const Allocator = std.mem.Allocator;

const EN_LONG = [12]f32{ 25.9250, 199.0233, 45.5058, 353.5444, 296.5714, 128.2950, 84.6114, 331.7575, 312.9464, 259.7942, 288.0864, 89.8081 };
const O_LONG = [12]f32{ 310.8772, 18.7233, 329.0186, 357.2664, 231.8581, 61.2367, 54.0903, 320.2503, 306.4319, 254.6811, 265.6008, 105.1958 };

pub const SynastrySparseAttentionLayer = struct {
    allocator: Allocator,
    heads: u32,
    head_dim: u32,
    sparsity_factor: f32,

    Wq: tensorcore.Tensor,
    Wk: tensorcore.Tensor,
    Wv: tensorcore.Tensor,
    Wo: tensorcore.Tensor,
    synastry_flat: [144]f32,

    pub fn init(allocator: Allocator, config: struct { heads: u32, head_dim: u32, sparsity_factor: f32 }, input_dim: u32) !SynastrySparseAttentionLayer {
        var self = SynastrySparseAttentionLayer {
            .allocator = allocator,
            .heads = config.heads,
            .head_dim = config.head_dim,
            .sparsity_factor = config.sparsity_factor,
            .Wq = undefined,
            .Wk = undefined,
            .Wv = undefined,
            .Wo = undefined,
            .synastry_flat = undefined,
        };
        self.Wq = tensorcore.tensor_init(allocator, &.{input_dim, config.heads * config.head_dim});
        self.Wk = tensorcore.tensor_init(allocator, &.{input_dim, config.heads * config.head_dim});
        self.Wv = tensorcore.tensor_init(allocator, &.{input_dim, config.heads * config.head_dim});
        self.Wo = tensorcore.tensor_init(allocator, &.{config.heads * config.head_dim, input_dim});
        self.computeSynastryBias();
        return self;
    }

    pub fn deinit(self: *SynastrySparseAttentionLayer) void {
        tensorcore.tensor_deinit(&self.Wq);
        tensorcore.tensor_deinit(&self.Wk);
        tensorcore.tensor_deinit(&self.Wv);
        tensorcore.tensor_deinit(&self.Wo);
    }

    fn computeSynastryBias(self: *SynastrySparseAttentionLayer) void {
        const aspects = [5]f32{ 0.0, 60.0, 90.0, 120.0, 180.0 };
        const aspect_signs = [5]f32{ 1.0, 0.8, -0.6, 0.8, -1.0 };
        for (0..12) |bi| {
            for (0..12) |bj| {
                var diff = math.fabs(EN_LONG[bi] - O_LONG[bj]);
                if (diff > 180.0) diff = 360.0 - diff;
                var score: f32 = 0.0;
                for (aspects, 0..) |asp, k| {
                    var orb = math.fabs(diff - asp);
                    if (orb > 180.0) orb = 360.0 - orb;
                    if (orb < 8.0) {
                        score += aspect_signs[k] * (1.0 - orb / 10.0);
                    }
                }
                self.synastry_flat[bi * 12 + bj] = score * 2.0;
            }
        }
    }

    pub fn forward(self: *SynastrySparseAttentionLayer, x: *tensorcore.Tensor) !tensorcore.Tensor {
        const seq_len = x.shape[0];
        const input_dim = x.shape[1];

        var Q = tensorcore.matmul(self.allocator, x, &self.Wq);
        defer tensorcore.tensor_deinit(&Q);
        var K = tensorcore.matmul(self.allocator, x, &self.Wk);
        defer tensorcore.tensor_deinit(&K);
        var V = tensorcore.matmul(self.allocator, x, &self.Wv);
        defer tensorcore.tensor_deinit(&V);

        var scores = tensorcore.matmul(self.allocator, &Q, &K);
        defer tensorcore.tensor_deinit(&scores);

        const scale = 1.0 / math.sqrt(@intToFloat(f32, self.head_dim));
        for (scores.data) |*s| {
            s.* *= scale;
        }

        for (0..seq_len) |i| {
            for (0..seq_len) |j| {
                const idx = i * seq_len + j;
                scores.data[idx] += self.synastry_flat[(i % 12) * 12 + (j % 12)];
            }
        }

        const threshold = self.findSparsityThreshold(&scores);
        for (scores.data) |*s| {
            if (s.* < threshold) {
                s.* = -1e9;
            }
        }

        try tensorcore.softmax(&scores, 1);

        var output = tensorcore.matmul(self.allocator, &scores, &V);
        defer tensorcore.tensor_deinit(&output);

        var final_output = tensorcore.matmul(self.allocator, &output, &self.Wo);
        return final_output;
    }

    fn findSparsityThreshold(self: *const SynastrySparseAttentionLayer, scores: *tensorcore.Tensor) f32 {
        var sorted_scores = self.allocator.alloc(f32, scores.data.len) catch unreachable;
        defer self.allocator.free(sorted_scores);
        @memcpy(sorted_scores, scores.data);
        std.sort.heap(f32, sorted_scores, {}, std.sort.desc(f32));

        const k = @floatToInt(usize, @intToFloat(f32, scores.data.len) * self.sparsity_factor);
        return sorted_scores[k];
    }
};

